import{c as e,Q as a,j as i,m as d}from"./chunks/framework.COywXlYp.js";const p=JSON.parse('{"title":"3.0.1.12rc1","description":"","frontmatter":{"title":"3.0.1.12rc1","layout":"doc"},"headers":[],"relativePath":"en/updatelog/beta/3/30112rc1.md","filePath":"en/updatelog/beta/3/30112rc1.md"}'),r={name:"en/updatelog/beta/3/30112rc1.md"};function n(o,t,s,l,u,c){return a(),i("div",null,[...t[0]||(t[0]=[d('<h1 id="_3-0-1-12rc1" tabindex="-1">3.0.1.12rc1 <a class="header-anchor" href="#_3-0-1-12rc1" aria-label="Permalink to &quot;3.0.1.12rc1&quot;">​</a></h1><p>Release Date: 2025/12/19</p><h2 id="update-content" tabindex="-1">Update Content <a class="header-anchor" href="#update-content" aria-label="Permalink to &quot;Update Content&quot;">​</a></h2><ul><li>Optimized language packs</li><li><ul><li>Modified the English language pack, fixed the issue where some version number characters displayed without spaces, and removed extra commas</li></ul></li><li><ul><li>Other language pack optimizations...</li></ul></li><li>Error style automatic uninstallation functionality</li><li>Fixed some bugs:</li><li><ul><li>After switching languages, the interface opened again would become the selected updated language, causing interface fragmentation</li></ul></li><li><ul><li>Fixed the issue where the English language pack had unexpected characters</li></ul></li><li><ul><li>Some other bugs...</li></ul></li><li><ul><li>Adjusted settings: Changed the &#39;Software needs to restart&#39; interface to a pop-up window and removed character display</li></ul></li><li><ul><li>Removed clickmouse initialization, now automatically gets language</li></ul></li></ul><h2 id="known-issues" tabindex="-1">Known Issues <a class="header-anchor" href="#known-issues" aria-label="Permalink to &quot;Known Issues&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Issue Description</th><th>Solution</th><th>Affected Version</th><th>Fixed Version</th><th>Status</th><th>Issue Link</th></tr></thead><tbody><tr><td>After settings trigger a restart, it returns to the first page</td><td>None</td><td>&gt;=3.0.0.11;&lt;3.0.3.14</td><td>3.0.3.14</td><td>Fixed</td><td><a href="https://github.com/xystudiocode/pyClickMouse/issues/42" target="_blank" rel="noreferrer">Issue Link</a></td></tr><tr><td>Settings cannot enable <code>Use default value when click count is wrong</code></td><td>None</td><td>&gt;=3.0.0.11;&lt;3.1.0.15</td><td>3.1.0.15</td><td>Fixed</td><td><a href="https://github.com/xystudiocode/pyClickMouse/issues/70" target="_blank" rel="noreferrer">Issue Link</a></td></tr><tr><td>If the release is a remastered version, it will not detect the update</td><td>None</td><td>&gt;=2.1.0.5;&lt;3.2.0.18beta7</td><td>3.2.0.18beta7</td><td>Fixed</td><td><a href="https://github.com/xystudiocode/pyClickMouse/issues/123" target="_blank" rel="noreferrer">Issue Link</a></td></tr><tr><td>When there is an update, opening the application from the tray shows there is an update, causing continuous pop-ups</td><td>None</td><td>&gt;=3.0.0.11</td><td>3.2.0.18beta7</td><td>Fixed</td><td><a href="https://github.com/xystudiocode/pyClickMouse/issues/132" target="_blank" rel="noreferrer">Issue Link</a></td></tr><tr><td>English mode cannot enable infinite clicking</td><td>None</td><td>&gt;=3.0.0.11</td><td>3.2.0.19beta9</td><td>Fixed</td><td><a href="https://github.com/xystudiocode/pyClickMouse/issues/168" target="_blank" rel="noreferrer">Issue Link</a></td></tr><tr><td>English mode &quot;Paused&quot; display error</td><td>None</td><td>&gt;=3.0.0.11</td><td>3.2.0.19beta9</td><td>Fixed</td><td><a href="https://github.com/xystudiocode/pyClickMouse/issues/169" target="_blank" rel="noreferrer">Issue Link</a></td></tr><tr><td>Unable to use the “Set Delay” function</td><td>None</td><td>&gt;3.0.0.11; &lt;3.2.0.19rc3</td><td>3.2.0.19rc3</td><td>Fixed</td><td><a href="https://github.com/xystudiocode/pyClickMouse/issues/207" target="_blank" rel="noreferrer">issue link</a></td></tr></tbody></table><h2 id="next-version-preview" tabindex="-1">Next Version Preview <a class="header-anchor" href="#next-version-preview" aria-label="Permalink to &quot;Next Version Preview&quot;">​</a></h2><p>Version number: 3.1.0.13 (tentative)</p><p>Expected update content:</p><ul><li>Add an initialization program, no need to replace folders</li><li>Add a package manager</li></ul><h2 id="download-link" tabindex="-1">Download Link <a class="header-anchor" href="#download-link" aria-label="Permalink to &quot;Download Link&quot;">​</a></h2><p><a href="https://github.com/xystudiocode/pyClickMouse/releases/tag/3.0.1.12rc1" target="_blank" rel="noreferrer">Click to download</a></p>',12)])])}const g=e(r,[["render",n]]);export{p as __pageData,g as default};
